// Guard: live text must equal audited old text; skip if already new; skip if last edited by a linguist.
const LING = 'qrcodelocalization@gmail.com sabrathan@gmail.com farahputri@gmail.com dmluciahorea@gmail.com roxanamoldovan25@gmail.com mteres@terestraducciones.com arandatrad@gmail.com sara.guinot.trad@gmail.com daniel@dgmultilingualservices.com root-translations@outlook.com austra.muizniece@gmail.com harald.roald@gmail.com 47natcha@gmail.com ellen.de.venter@outlook.com ilaria.roncaglia@gmail.com silke.luehrmann@gmx.de boh.vozniuk@gmail.com vidiasc@gmail.com ivanaturcin@ymail.com julius.valkiunas@gmail.com jaromirvicari@me.com karahansisman@gmail.com katri.varvikko@gmail.com kenneth@phraseit.dk translation@cornell.hu ruckova.lucia@gmail.com marit.teichmann@gmail.com michal.tosza@translators.org.pl mteixeira@sacradomus.com bruno@bsttranslations.com nerissaneptuno@gmail.com straus.translations@gmail.com quentinnguyen.localize@gmail.com therese.svardsten@gmail.com mjlocalize@gmail.com silis.martins@gmail.com'.split(' ');
const cfg = $('Config').all(); const live = $input.all(); const out = []; const skipped = [];
for (let i = 0; i < cfg.length; i++) { const c = cfg[i].json; const b = (live[i] && live[i].json) || {}; const t = b.translation || {};
  const cur = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation);
  if (!t.translation_id) { skipped.push({ key: c.key, iso: c.iso, why: 'fetch failed' }); continue; }
  if (cur === c.new) { skipped.push({ key: c.key, iso: c.iso, why: 'already' }); continue; }
  if (cur !== c.old) { skipped.push({ key: c.key, iso: c.iso, why: 'changed', live: cur }); continue; }
  if (LING.indexOf(t.modified_by_email) >= 0) { skipped.push({ key: c.key, iso: c.iso, why: 'linguist edit', by: t.modified_by_email }); continue; }
  out.push({ json: Object.assign({}, c) }); }
if (out.length) out[0].json._skipped = skipped;
return out;

const cfg = $('Guard').all().map(function (x) { return x.json; }); const rb = $input.all(); const res = [];
for (let i = 0; i < cfg.length; i++) { const c = cfg[i]; const t = (rb[i] && rb[i].json && rb[i].json.translation) || {};
  res.push({ key: c.key, iso: c.iso, ok: t.translation === c.new, live: t.translation }); }
return [{ json: { written: res.length, ok: res.filter(function (r) { return r.ok; }).length, results: res, skipped: (cfg[0] && cfg[0]._skipped) || [] } }];
